{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Tolfenamic acid, a close-transfer aromatic carboxylic acid/amine drug, showed absolute oral bioavailability of about 100% in patients and 55–91% across healthy/cirrhotic cohorts, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "PABA, which shares the para-aminophenyl substructure with the query, had oral bioavailability of 90.1% in CF patients, demonstrating that the aniline-containing scaffold is well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Selurampanel, a sulfonamide-containing drug, had absolute oral bioavailability of approximately 60–70% in humans, directly supporting high F for this sulfonamide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Amrinone, a small heteroaromatic amine, showed 90–95% oral bioavailability in healthy subjects, supporting high absorption for the query's heteroaromatic amine/sulfonamide framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "PF-592379, an aminopyridine-containing small molecule, had predicted complete absorption and >60% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "6-MNA, a small aromatic acid metabolite, had absolute oral bioavailability of 35–38%, still well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Acalabrutinib, a more complex drug, had absolute oral bioavailability of 25% in humans, confirming that even moderate F values in this evidence set remain above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Para-aminosalicylic acid, which contains the same para-aminophenyl motif, had oral bioavailability of 50–60% in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability ≥20%, with most ≥50%; the query's small sulfonamide/aniline structure is consistent with these high-F drugs, so predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "No low-bioavailability analogue with comparable transfer score was provided.",
    "Physicochemical prior is mixed due to ionization and TPSA, but consistent experimental evidence outweighs it."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

